import{z as i,x as p,o as e,c as d,q as t,j as E,D as r,d as s,s as n,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const v=JSON.parse('{"title":"Borůvka 与次小生成树","description":"","frontmatter":{"title":"Borůvka 与次小生成树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/boruvka-second-mst.md","filePath":"cs/boruvka-second-mst.md","lastUpdated":1791063341000}'),A={name:"cs/boruvka-second-mst.md"};function m(u,a,T,k,c,S){const o=p("Mermaid");return e(),d("div",null,[a[2]||(a[2]=t('<h1 id="boruvka-与次小生成树" tabindex="-1">Borůvka 与次小生成树 <a class="header-anchor" href="#boruvka-与次小生成树" aria-label="Permalink to &quot;Borůvka 与次小生成树&quot;">​</a></h1><div class="epigraph"><p>每个连通块同时抓住出块最轻边，一轮收缩；次小生成树则在 MST 上换一条边：树上路径最大边与非树边的最小正替换。</p><footer>—— 据 Borůvka, 1926；Tarjan, Sensitivity Analysis of Minimum Spanning Trees, 1982；CLRS 第 23 章整理</footer></div><p>上一课<a href="/cs/kruskal-reconstruction">Kruskal 重构树</a>把 MST 加边史做成查询树。主干 Kruskal/Prim 已给一棵 MST。缺口有两块：Borůvka 的<strong>并行长树</strong>（也是切分定理），以及<strong>严格次小生成树</strong>——边集不同、权和次小。不重写切分定理。后课离开生成树，进入费用流。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Borůvka：初始每个点一块。同步：每块选一条跨块最轻边（平权要定规则以免环）。加入这些边，收缩。至多 \\(O(\\log n)\\) 轮，每轮 \\(O(E)\\)，总 \\(O(E\\log V)\\)。适合并行；也是 Prim/Kruskal 之外第三种经典 MST。</p><p>次小：在 MST \\(T\\) 上，对每条非树边 \\((u,v)\\)，替换 \\(T\\) 上 \\(u\\)–\\(v\\) 路径的最大边，得到另一棵生成树。所有这种替换里权和最小者即（严格）次小——若要求边集不同，平权时可能要次小替换。实现：树上倍增维护路径 \\(\\max\\)，扫非树边 \\(O(E\\log V)\\)。</p><p>缺口是「换一条边」，不是再求 MST。</p><h3 id="次小不是次小边" tabindex="-1">次小不是次小边 <a class="header-anchor" href="#次小不是次小边" aria-label="Permalink to &quot;次小不是次小边&quot;">​</a></h3><p>次小生成树与「第二小的那条边」无关。可能换掉的是内部一条大边。也不要 Borůvka 每块选次轻当次小树——那一般错。</p><p><span class="marginnote">Borůvka 1926（Otakar Borůvka）早于 Kruskal/Prim。次小生成树的替换分析见 Tarjan 等关于 MST 敏感度的工作。CLRS 23 点名 Borůvka。后课最小费用流换容量与费用，不再是无向生成树。</span></p><p><span class="marginnote">直觉类比：Borůvka 像<strong>村庄并网</strong>——每个村各自拉一条通往邻村的 cheapest 电线，一轮下来村庄数至少减半；重复几轮，全国电网成型。各「村」互不商量，所以天然适合并行。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>MST：Borůvka 或沿用 Kruskal。次小：先 MST；预处理树路径 \\(\\max\\)；枚举非树边算 \\(\\Delta=w(e)-\\maxPath\\)；取最小正 \\(\\Delta\\) 加上 \\(w(T)\\)。\\(\\Delta=0\\) 表示有另一棵同权 MST。</p>',13)),(e(),E(l,null,{default:r(()=>[n(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22Bor%C5%AFvka%20%E5%90%8C%E6%AD%A5%E5%8A%A0%E6%9C%80%E8%BD%BB%E5%87%BA%E8%BE%B9%22%5D%20--%3E%20MST%5B%22%E6%9C%80%E5%B0%8F%E7%94%9F%E6%88%90%E6%A0%91%20T%22%5D%0A%20%20MST%20--%3E%20REP%5B%22%E9%9D%9E%E6%A0%91%E8%BE%B9%E6%9B%BF%E6%8D%A2%E8%B7%AF%E5%BE%84%20max%22%5D%0A%20%20REP%20--%3E%20SEC%5B%22%E6%AC%A1%E5%B0%8F%E7%94%9F%E6%88%90%E6%A0%91%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("p",null,"不连通则生成森林，次小说同一连通块内。",-1)),a[4]||(a[4]=B("p",null,"非树边 \\((u,v)\\) 进场时，树上 \\(u\\)–\\(v\\) 路径该删谁？",-1)),(e(),E(l,null,{default:r(()=>[n(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20ADD%5B%22%E5%8A%A0%E9%9D%9E%E6%A0%91%E8%BE%B9%20e%EF%BC%9A%E6%88%90%E7%8E%AF%22%5D%20--%3E%20FIND%5B%22%E6%89%BE%E7%8E%AF%E4%B8%8A%20u%E2%80%93v%20%E8%B7%AF%E5%BE%84%E7%9A%84%E6%9C%80%E5%A4%A7%E8%BE%B9%20m%22%5D%0A%20%20FIND%20--%3E%20CMP%7B%22%E6%AF%94%E8%BE%83%20w(e)%20%E4%B8%8E%20w(m)%22%7D%0A%20%20CMP%20--%3E%7C%22%E6%9B%B4%E5%B0%8F%22%7C%20SW%5B%22%E5%88%A0%20m%EF%BC%9A%E6%9D%83%E5%8F%98%E5%B0%8F%20%E2%86%92%20%E6%9B%B4%E4%BC%98%E6%A0%91%22%5D%0A%20%20CMP%20--%3E%7C%22%E7%9B%B8%E7%AD%89%22%7C%20EQ%5B%22%E5%90%8C%E6%9D%83%E5%8F%A6%E4%B8%80%E6%A3%B5%20MST%22%5D%0A%20%20CMP%20--%3E%7C%22%E6%9B%B4%E5%A4%A7%22%7C%20BAD%5B%22%E5%88%A0%20m%20%E5%8F%8D%E8%80%8C%E6%9B%B4%E8%B4%B5%EF%BC%9A%E6%94%BE%E5%BC%83%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<p><span class="marginnote">数字实例：MST 上 \\(u\\)–\\(v\\) 路径边权为 \\(\\{3,8,5\\}\\)，路径最大边 \\(=8\\)。某条权为 \\(6\\) 的非树边换掉它，新树权 \\(=w(T)+6-8=w(T)-2\\)，更小——但 MST 已最小，说明此情形不可能；合法替换的最小正 \\(\\Delta\\) 才给出次小树。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Borůvka 每轮块数至少减半（每块至少合一次，若图连通），故对数轮。安全边仍来自切分。替换定理：任一与 \\(T\\) 差一条边的生成树都是「加非树边、删圈上另一边」；权和变小当且仅当删的比加的重。故最优次小在「删路径最大边」里产生。</p><p>与重构树：LCA 给出路径 \\(\\max\\)，正是本课替换要用的量。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 \\(k\\) 小生成树枚举全套、不写有向 Chu–Liu。动态 MST 不写。后课默认：MST 三种经典算法；次小 = 树上路径 max 替换。下一课最小费用最大流，边有容量与费用。</p><p><span class="marginnote">常见误区：把「次小生成树」理解成「用第二便宜的边拼树」，或者 Borůvka 每块顺手存次轻边当次小树——都不对。次小是<strong>整树权</strong>排名第二，可能动的是树内部某条大边，且必须先有完整 MST 再做替换。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Borůvka：块同步抓最轻出边，对数轮。</li><li>次小生成树：MST 上非树边替换路径最大边。</li><li>切分定理共用；与瓶颈重构树接口是路径 \\(\\max\\)。</li><li>出处：Borůvka, 1926；MST 敏感度见 Tarjan, 1982；CLRS 第 23 章。</li></ul>',9))])}const C=i(A,[["render",m]]);export{v as __pageData,C as default};
